PLANTILLA_LAMINA_S3 = """
<style>
  .b {font-size:16px;padding:8px 12px;cursor:pointer;border-radius:6px;
      border:1px solid #888;background:#fff;color:#111;}
  .b:disabled {opacity:.45;cursor:default;}
  .t {font-weight:bold;margin:10px 0 4px;}
</style>
<div style="font-family:sans-serif;max-width:800px;color:#111;background:#fff;
     padding:10px;border-radius:8px;">
  <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
    <button id="ini" class="b">▶️ Comenzar</button>
    <span id="reloj" style="font-size:22px;font-weight:bold;min-width:110px;">
      ⏱️ __TIEMPO__</span>
    <button id="deshacer" class="b" disabled>↩️ Deshacer última marca</button>
    <button id="fin" class="b" disabled>✅ Terminé</button>
  </div>
  <div id="velo" style="margin-top:12px;padding:18px;background:#EAF2FB;
       border-radius:8px;font-size:17px;">
    Cuando estés listo, pulsa <b>Comenzar</b>. Aparecerán dos imágenes: la
    IMAGEN 1 es el modelo y en la IMAGEN 2 hay <b>__NDIF__ diferencias</b>.
    Haz clic sobre cada diferencia que encuentres. Tienes __MINUTOS__ minutos.
  </div>
  <div id="zona" style="display:none;">
    <div class="t">IMAGEN 1 — Modelo</div>
    <img src="__MODELO__" style="width:100%;display:block;border:1px solid #ccc;">
    <div class="t">IMAGEN 2 — Haz clic sobre cada diferencia que encuentres</div>
    <canvas id="c" style="width:100%;display:block;border:1px solid #ccc;
            cursor:crosshair;"></canvas>
  </div>
  <div id="res" style="display:none;margin-top:12px;padding:14px;
       background:#FFF4E5;border-radius:8px;font-size:18px;"></div>
</div>
<script>
  const DIFS = __DIFS__;
  const TOTAL = __SEG__;
  const PAD = 25;
  const cv = document.getElementById("c");
  const ctx = cv.getContext("2d");
  const img = new Image();
  img.onload = function() {
    cv.width = img.naturalWidth;
    cv.height = img.naturalHeight;
    dibujar(false);
  };
  img.src = "__MODIFICADA__";

  let marcas = [], activo = false, t0 = 0, timer = null;

  function fmt(s) {
    s = Math.max(0, Math.ceil(s));
    return String(Math.floor(s / 60)).padStart(2, "0") + ":" +
           String(s % 60).padStart(2, "0");
  }
  function dibujar(revelar) {
    ctx.clearRect(0, 0, cv.width, cv.height);
    ctx.drawImage(img, 0, 0);
    if (revelar) {
      const hall = calcular().hall;
      DIFS.forEach(function(b, i) {
        ctx.lineWidth = 6;
        ctx.setLineDash(hall.has(i) ? [] : [14, 10]);
        ctx.strokeStyle = hall.has(i) ? "#1a9a3a" : "#f08000";
        ctx.strokeRect(b[0], b[1], b[2] - b[0], b[3] - b[1]);
      });
      ctx.setLineDash([]);
    }
    marcas.forEach(function(m) {
      ctx.beginPath();
      ctx.arc(m.x, m.y, 36, 0, 6.2832);
      ctx.lineWidth = 7;
      ctx.strokeStyle = "#e00000";
      ctx.stroke();
    });
  }
  function grupoEn(x, y) {
    for (let i = 0; i < DIFS.length; i++) {
      const b = DIFS[i];
      if (x >= b[0] - PAD && x <= b[2] + PAD && y >= b[1] - PAD && y <= b[3] + PAD) return i;
    }
    return -1;
  }
  function calcular() {
    const hall = new Set();
    let errores = 0;
    marcas.forEach(function(m) { if (m.g >= 0) hall.add(m.g); else errores++; });
    return {hall: hall, a: hall.size, e: errores};
  }
  function finalizar(porTiempo) {
    if (!activo) return;
    activo = false;
    clearInterval(timer);
    const usado = Math.min(TOTAL, (Date.now() - t0) / 1000);
    const r = calcular();
    dibujar(true);
    document.getElementById("deshacer").disabled = true;
    document.getElementById("fin").disabled = true;
    const res = document.getElementById("res");
    res.style.display = "block";
    res.innerHTML = (porTiempo ? "⏳ <b>Se acabó el tiempo.</b><br>" : "✅ <b>Terminaste.</b><br>") +
      "Aciertos: <b>" + r.a + "</b> de " + DIFS.length +
      " &nbsp;·&nbsp; Errores (marcas sin diferencia): <b>" + r.e + "</b>" +
      " &nbsp;·&nbsp; Tiempo usado: <b>" + fmt(usado) + "</b>" +
      "<br><span style='font-size:15px'>Verde = encontradas · Naranja punteado = " +
      "las que faltaron. Escribe estos datos en el formulario de abajo.</span>";
  }
  document.getElementById("ini").onclick = function() {
    activo = true;
    t0 = Date.now();
    this.disabled = true;
    document.getElementById("fin").disabled = false;
    document.getElementById("velo").style.display = "none";
    document.getElementById("zona").style.display = "block";
    timer = setInterval(function() {
      const resto = TOTAL - (Date.now() - t0) / 1000;
      document.getElementById("reloj").textContent = "⏱️ " + fmt(resto);
      if (resto <= 0) finalizar(true);
    }, 250);
  };
  document.getElementById("fin").onclick = function() { finalizar(false); };
  document.getElementById("deshacer").onclick = function() {
    if (!activo) return;
    marcas.pop();
    dibujar(false);
    this.disabled = marcas.length === 0;
  };
  cv.addEventListener("click", function(ev) {
    if (!activo) return;
    const r = cv.getBoundingClientRect();
    const x = (ev.clientX - r.left) * (cv.width / r.width);
    const y = (ev.clientY - r.top) * (cv.height / r.height);
    marcas.push({x: x, y: y, g: grupoEn(x, y)});
    document.getElementById("deshacer").disabled = false;
    dibujar(false);
  });
</script>
"""


@st.cache_data(show_spinner=False)
def _imagen_b64(nombre_archivo):
    """Devuelve una lámina como data URI (incrustada; si no, de laminas_s3/)."""
    incrustada = IMAGENES_S3_EMBEBIDAS.get(nombre_archivo)
    if incrustada:
        return "data:image/png;base64," + incrustada
    ruta = os.path.join(RUTA_LAMINAS_S3, nombre_archivo)  # respaldo: carpeta
    if not os.path.exists(ruta):
        return None
    with open(ruta, "rb") as f:
        return "data:image/png;base64," + base64.b64encode(f.read()).decode()


@st.cache_data(show_spinner=False)
def _html_lamina_s3(nivel, letra, segundos):
    modelo = _imagen_b64(f"lamina_{letra}_{nivel}_modelo.png")
    modificada = _imagen_b64(f"lamina_{letra}_{nivel}_modificada.png")
    if modelo is None or modificada is None:
        return None, 0
    difs = DIFERENCIAS_S3[f"{letra}_{nivel}"]
    # alto del iframe: dos imágenes a un ancho máximo de 800 px + controles
    ancho, alto = (1100, 660) if nivel == "bajo" else (
        (1650, 660) if nivel == "medio" else (1650, 990)
    )
    altura = int(2 * 800 * alto / ancho + 330)
    minutos = f"{segundos // 60}" if segundos % 60 == 0 else f"{segundos / 60:.1f}"
    html = (
        PLANTILLA_LAMINA_S3.replace("__DIFS__", json.dumps(difs))
        .replace("__SEG__", str(int(segundos)))
        .replace("__TIEMPO__", f"{segundos // 60:02d}:{segundos % 60:02d}")
        .replace("__MINUTOS__", minutos)
        .replace("__NDIF__", str(len(difs)))
        .replace("__MODELO__", modelo)
        .replace("__MODIFICADA__", modificada)
    )
    return html, altura


def lamina_s3(nivel, letra, segundos):
    """Lámina interactiva + formulario de registro. Devuelve dict o None."""
    clave = f"s3_reg_{letra}"
    n_dif = len(DIFERENCIAS_S3[f"{letra}_{nivel}"])
    if clave in st.session_state:
        r = st.session_state[clave]
        st.success(
            f"Lámina {letra} registrada: {r['aciertos']} de {n_dif} diferencias"
            f" · {r['errores']} errores · tiempo {r['tiempo']} · batería"
            f" {r['bateria']}/10."
        )
        return r

    html, altura = _html_lamina_s3(nivel, letra, segundos)
    if html is None:
        st.error(
            "No se encontraron las imágenes de las láminas de esta sesión."
        )
        return None
    st.caption(
        f"Tiempo de esta lámina: {segundos // 60} min (se ajusta a tu nivel de"
        " fatiga: más fatiga, más tiempo). No se usa lápiz: haz clic sobre cada"
        " diferencia."
    )
    components.html(html, height=altura, scrolling=False)
    with st.form(f"s3_form_{letra}"):
        st.markdown(f"**Registra el resultado de la Lámina {letra}** (copia los"
                    " datos que aparecieron al terminar):")
        c1, c2, c3 = st.columns(3)
        with c1:
            aciertos = st.number_input(
                f"Aciertos (de {n_dif}):", 0, n_dif, 0, key=f"s3_f_ac_{letra}"
            )
        with c2:
            errores = st.number_input(
                "Errores:", 0, 99, 0, key=f"s3_f_er_{letra}"
            )
        with c3:
            tiempo = st.text_input(
                "Tiempo usado (mm:ss):", key=f"s3_f_ti_{letra}"
            )
        bateria = st.slider(
            "Batería mental ahora:",
            1,
            10,
            st.session_state.bateria_actual,
            key=f"s3_f_ba_{letra}",
        )
        enviado = st.form_submit_button("💾 Registrar resultado", type="primary")
    if enviado:
        st.session_state[clave] = {
            "aciertos": int(aciertos),
            "errores": int(errores),
            "tiempo": tiempo.strip() or "—",
            "bateria": int(bateria),
        }
        st.rerun()
    return None


def sesion_3():
    st.subheader("Sesión 3: Mi batería mental y pausa estratégica")
    nivel = abrir_sesion(3)
    if nivel is None:
        return
    st.markdown(
        "**Instrucciones:** 1) Repasa lo aprendido antes. 2) Marca las señales"
        " que notas cuando tu batería baja. 3) Lámina A: compara dos imágenes"
        " y haz clic sobre cada diferencia. 4) Haz una pausa de 3 minutos."
        " 5) Lámina B: repite la búsqueda de diferencias."
    )

    # ---- 1. Repaso
    st.markdown("#### 🔁 1. Repaso: lo que aprendimos antes")
    st.info(
        "**Sesión 1:** los 4 pasos de ejecución segura (Recibir → Revisar →"
        " Realizar → Comprobar) y la estrategia **Miro → Señalo → Compruebo**."
        "\n\n**Sesión 2:** las fichas Azul (rutina), Verde (sin ayuda o tras"
        " pausa) y Naranja (interrupción o con apoyo), y registrar la hora."
    )
    repaso = [
        (
            "¿Qué significa «Miro → Señalo → Compruebo»?",
            "Mirar dónde me quedé, señalarlo y comprobar antes de seguir.",
        ),
        (
            "¿Qué significa cada ficha (Azul, Verde, Naranja)?",
            "Azul: rutina normal · Verde: sin ayuda o tras pausa · Naranja:"
            " tras interrupción o con apoyo.",
        ),
        (
            "Nombra los 4 pasos de ejecución segura.",
            "Recibir el recordatorio, revisar la indicación, realizar la"
            " actividad y comprobar/registrar.",
        ),
        (
            "¿Qué haces si suena una alarma y estás ocupado?",
            "Detengo la actividad, marco dónde me quedé, atiendo la alarma,"
            " registro y retomo.",
        ),
    ]
    n_rep = por_nivel(nivel, 2, 3, 4)
    respuestas_repaso = []
    for i, (preg, _) in enumerate(repaso[:n_rep]):
        respuestas_repaso.append(st.text_input(preg, key=f"s3_rep_{i}"))
    if st.checkbox("Ver respuestas de referencia del repaso", key="s3_rep_ver"):
        for preg, ref in repaso[:n_rep]:
            st.caption(f"• {preg} → {ref}")

    # ---- 2. Señales
    st.markdown("#### 🔎 2. Mis señales de fatiga")
    senales = st.multiselect(
        "Señales cuando la batería baja de 4 (somáticas o mentales):",
        SENALES_S3,
        key="s3_senales",
    )
    otros = ""
    if "Otros" in senales:
        otros = st.text_input("Otros: ¿cuáles?", key="s3_otros")

    # ---- 3. Lámina A
    segundos = TIEMPO_LAMINA_S3[nivel]
    st.markdown("#### 🖼️ 3. Lámina A (antes de la pausa de 3 min)")
    reg_a = lamina_s3(nivel, "A", segundos)
    if reg_a is None:
        return

    # ---- 4. Pausa
    st.markdown("#### ⏸️ 4. Pausa de 3 minutos")
    pausa = st.session_state.get("s3_pausa", 0)
    if pausa == 0:
        st.write(
            "Cuando estés listo, pulsa el botón. Descansa los ojos, respira"
            " lento y no uses el celular."
        )
        if st.button("▶️ Iniciar pausa de 3 minutos", key="s3_btn_pausa"):
            st.session_state.s3_pausa = 1
            st.rerun()
        return
    if pausa == 1:
        cuenta_regresiva(180, "⏸️ Pausa estratégica: respira y descansa")
        if st.button("✅ Terminé la pausa", key="s3_btn_fin_pausa"):
            st.session_state.s3_pausa = 2
            st.rerun()
        return

    # ---- 5. Lámina B
    st.markdown("#### 🖼️ 5. Lámina B (después de la pausa)")
    reg_b = lamina_s3(nivel, "B", segundos)
    if reg_b is None:
        return

    semaforo = st.selectbox(
        "Tarjeta del Semáforo de Autorregulación seleccionada:",
        [
            "🟢 Verde: Continuar la actividad",
            "🟡 Amarillo: Pausa corta / Reducir exigencia del estímulo",
            "🔴 Rojo: Detener la tarea y solicitar apoyo externo",
        ],
        key="s3_semaforo",
    )

    n_dif = len(DIFERENCIAS_S3[f"A_{nivel}"])
    detalle = (
        f"Nivel {nivel} | Tiempo por lámina: {segundos // 60} min | Repaso"
        f" respondido: {sum(1 for r in respuestas_repaso if r.strip())}/{n_rep}"
        f" | Lámina A: {reg_a['aciertos']}/{n_dif} aciertos,"
        f" {reg_a['errores']} errores, tiempo {reg_a['tiempo']} (Batería"
        f" {reg_a['bateria']}) → Lámina B: {reg_b['aciertos']}/{n_dif}"
        f" aciertos, {reg_b['errores']} errores, tiempo {reg_b['tiempo']}"
        f" (Batería {reg_b['bateria']}) | Semáforo: {semaforo} | Señales:"
        f" {', '.join(senales)}"
        + (f" | Otros: {otros}" if otros else "")
    )
    resumen = (
        f"Lámina A: {reg_a['aciertos']} de {n_dif} diferencias. Lámina B:"
        f" {reg_b['aciertos']} de {n_dif} diferencias."
    )
    cerrar_sesion(3, "Batería Mental y Pausa", detalle, resumen)


